use vstd::prelude::*;

verus! {

/// Given a slice `a: &[int]` and a start index `i`, return an index `m`
/// such that
///   1. `i <= m < a.len()`, and
///   2. for all `k` in `i..a.len()`, `a[m] <= a[k]`.
fn look_for_min(a: &[int], i: usize) -> (m: usize)
    requires
        i < a.len(),
    ensures
        i <= m,
        m < a.len(),
        forall |k: usize| (i <= k && k < a.len()) ==> a[m] <= a[k],
{
    let n = a.len();
    // Candidate for the minimum index in the suffix [i, n)
    let mut min_idx: usize = i;
    // We will scan from j = i+1 up to n
    let mut j: usize = i + 1;
    while j < n
        invariant
            // min_idx remains in the valid suffix
            i <= min_idx,
            min_idx < n,
            // j stays between i and n
            i <= j,
            j <= n,
            // min_idx is the index of a least element in [i, j)
            forall |k: usize| (i <= k && k < j) ==> a[min_idx] <= a[k],
        decreases n - j,
    {
        if a[j] < a[min_idx] {
            min_idx = j;
        }
        j += 1;
    }
    min_idx
}

}

